PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?film ?filmLabel (MIN(?date) AS ?earliestDirectorDeath) WHERE {
  VALUES ?film { <http://dbpedia.org/resource/Johnny,_You're_Wanted> <http://dbpedia.org/resource/The_Heart_of_Ezra_Greer> }
  ?film (dbo:director | dbp:director) ?director .
  OPTIONAL {
    { ?director dbo:deathDate ?d . BIND(xsd:date(?d) AS ?date) }
    UNION
    { ?director dbo:wikiPageRedirects ?dres . ?dres dbo:deathDate ?d2 . BIND(xsd:date(?d2) AS ?date) }
    UNION
    { ?director owl:sameAs ?dres2 . ?dres2 dbo:deathDate ?d3 . BIND(xsd:date(?d3) AS ?date) }
  }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = 'en') }
} GROUP BY ?film ?filmLabel
ORDER BY ?earliestDirectorDeath
LIMIT 1

